test("Alt を押しながら右辺を動かしている間、右の最初に当たる相手（親の縁）までの距離だけが出る", () => {
  renderCanvas({ selection: setupSelection(["badge"]) });
  drawnApart();
  const badge = drawnAt("badge", BadgeBounds);

  // 左（`home` の縁まで 20）・上（20）・下（`marker` まで 40）は出ない
  pressPointer(badge, { x: 218, y: 100 });
  movePointer(badge, { x: 238, y: 100 }, "alt");

  expect(sortedFacingDistanceLabels()).toEqual(["220"]);
});

test("Alt を押しながら右下の角を動かしている間、右と下の最初に当たる相手までの距離が出る", () => {
  renderCanvas({ selection: setupSelection(["badge"]) });
  drawnApart();
  const badge = drawnAt("badge", BadgeBounds);

  // 右辺 240・下辺 130。右は `home` の縁まで 220、下は `marker` まで 30
  pressPointer(resizeHandleAt({ x: 1, y: 1 }), { x: 220, y: 120 });
  movePointer(badge, { x: 240, y: 130 }, "alt");

  expect(sortedFacingDistanceLabels()).toEqual(["220", "30"]);
});

test("Alt を押さずに動かしている間は、距離が出ない", () => {
  renderCanvas({ selection: setupSelection(["badge"]) });
  drawnApart();
  const badge = drawnAt("badge", BadgeBounds);

  pressPointer(badge, { x: 218, y: 100 });
  movePointer(badge, { x: 238, y: 100 });

  expect(sortedFacingDistanceLabels()).toEqual([]);
});

test("Alt を押さずに動かしてから Alt を押して動かすと、距離が出る", () => {
  renderCanvas({ selection: setupSelection(["badge"]) });
  drawnApart();
  const badge = drawnAt("badge", BadgeBounds);

  pressPointer(badge, { x: 218, y: 100 });
  movePointer(badge, { x: 228, y: 100 });
  movePointer(badge, { x: 238, y: 100 }, "alt");

  expect(sortedFacingDistanceLabels()).toEqual(["220"]);
});

test("Alt を押して距離を出したあと、離して動かすと距離が消える", () => {
  renderCanvas({ selection: setupSelection(["badge"]) });
  drawnApart();
  const badge = drawnAt("badge", BadgeBounds);

  pressPointer(badge, { x: 218, y: 100 });
  movePointer(badge, { x: 238, y: 100 }, "alt");
  movePointer(badge, { x: 239, y: 100 });

  expect(sortedFacingDistanceLabels()).toEqual([]);
});

test("ポインタを離すと、距離が消える", () => {
  renderCanvas({ selection: setupSelection(["badge"]) });
  drawnApart();
  const badge = drawnAt("badge", BadgeBounds);

  pressPointer(badge, { x: 218, y: 100 });
  movePointer(badge, { x: 238, y: 100 }, "alt");
  releasePointer(badge, { x: 238, y: 100 });

  expect(sortedFacingDistanceLabels()).toEqual([]);
});

test("倍率を上げて動かしている間も、距離はドキュメント上の px で出る", () => {
  renderCanvas({ selection: setupSelection(["badge"]) });
  wheel(canvasSurface(), { x: 0, y: -100 }, "ctrl");

  // 1.2 倍で見ているときの描かれた矩形（`drawnApart` の並びを 1.2 倍したもの）
  drawnAt("home", { left: 120, top: 72, width: 432, height: 288 });
  drawnAt("marker", { left: 144, top: 192, width: 171.6, height: 48 });
  drawnAt("settings", { left: 600, top: 72, width: 360, height: 288 });
  const badge = drawnAt("badge", {
    left: 144,
    top: 96,
    width: 120,
    height: 48,
  });

  /*
   * 画面上で 24 動かすと幅は 20 伸び、右辺は画面上で 288。`home` の右の縁 552 まで画面上で
   * 264・ドキュメント上で 220。倍率を表示へ渡し忘れると画面上の値（264）が出る。
   */
  pressPointer(badge, { x: 262, y: 120 });
  movePointer(badge, { x: 286, y: 120 }, "alt");

  expect(sortedFacingDistanceLabels()).toEqual(["220"]);
});

test("Alt を押したままでも掴んだ辺は吸い付き、吸い付いたあとの辺から測る", () => {
  renderCanvas({ selection: setupSelection(["badge"]) });
  drawnApart();
  const badge = drawnAt("badge", BadgeBounds);

  // 右辺は 260 まで来て `marker` の右辺 263 へ吸い付く。吸い付かなければ 200
  pressPointer(badge, { x: 218, y: 100 });
  movePointer(badge, { x: 258, y: 100 }, "alt");

  expect(sortedFacingDistanceLabels()).toEqual(["197"]);
});

test("⌘ と Alt を押しながら動かすと、吸い付かない位置から測る", () => {
  renderCanvas({ selection: setupSelection(["badge"]) });
  drawnApart();
  const badge = drawnAt("badge", BadgeBounds);

  pressPointer(badge, { x: 218, y: 100 });
  movePointer(badge, { x: 258, y: 100 }, "meta+alt");

  expect(sortedFacingDistanceLabels()).toEqual(["200"]);
});

test("Alt を押しながら artboard の右辺を動かすと、右の artboard までの距離が出る", () => {
  renderCanvas({ selection: setupSelection(["home"]) });
  drawnApart();
  const home = drawnAt("home", HomeBounds);

  // 右辺は 472 まで来る。`settings` の左辺 500 まで 28
  pressPointer(home, { x: 458, y: 280 });
  movePointer(home, { x: 470, y: 280 }, "alt");

  expect(sortedFacingDistanceLabels()).toEqual(["28"]);
});

test("Alt を押しながら動かしても、今の親が大きさを持たずに描かれているなら距離は出ない", () => {
  renderCanvas({ selection: setupSelection(["badge"]) });
  // `home` は描かずに大きさ 0 のまま、兄弟の `marker` だけを描く
  drawnAt("marker", { left: 120, top: 160, width: 143, height: 40 });
  const badge = drawnAt("badge", BadgeBounds);

  /*
   * 右下の角を運び、右辺は 260 で `marker` の右辺 263 へ吸い付き、下辺は 130 で `marker` まで
   * 30 手前に来る。`marker` は測れていて吸い付きは出るので、距離が出ない理由は親の大きさが 0 なことだけ
   */
  pressPointer(resizeHandleAt({ x: 1, y: 1 }), { x: 220, y: 120 });
  movePointer(badge, { x: 260, y: 130 }, "alt");

  expect(snapGuides().length).toBeGreaterThan(0);
  expect(sortedFacingDistanceLabels()).toEqual([]);
});

test("リサイズハンドルを掴んでいる間は、Alt を押しても選択しているだけのときの距離は出ない", () => {
  renderCanvas({ selection: setupSelectionForResize(["badge"]) });
  drawnApartForResize();
  enterPointer(canvasSurface());
  pressPointer(resizeHandleAt({ x: 1, y: 1 }), { x: 220, y: 120 });

  holdAlt();

  expect(sortedFacingDistanceLabels()).toEqual([]);
});

test("右辺だけを掴んで動かすと、左・上・下に相手がいても右の相手までの距離だけが出る", () => {
  const resize = grabbedWithTargets(
    { x: 1, y: 0.5 },
    { x: 300, y: 100 },
    {
      names: WithinParent,
      boundsByName: DrawnBounds,
    },
  );

  expect(spansOf(distancesAt(resize, { x: 320, y: 100 }))).toEqual({
    horizontal: {
      start: Option.none,
      end: Option.some({ min: 320, max: 400 }),
    },
    vertical: { start: Option.none, end: Option.none },
  });
});

test("右下の角を掴んで動かすと、右と下の相手までの距離が出る", () => {
  const resize = grabbedWithTargets(
    { x: 1, y: 1 },
    { x: 300, y: 150 },
    {
      names: WithinParent,
      boundsByName: DrawnBounds,
    },
  );

  expect(spansOf(distancesAt(resize, { x: 320, y: 170 }))).toEqual({
    horizontal: {
      start: Option.none,
      end: Option.some({ min: 320, max: 400 }),
    },
    vertical: { start: Option.none, end: Option.some({ min: 170, max: 200 }) },
  });
});

test("右上の角を掴んで動かすと、右と上の相手までの距離が出る", () => {
  const resize = grabbedWithTargets(
    { x: 1, y: 0 },
    { x: 300, y: 50 },
    {
      names: WithinParent,
      boundsByName: DrawnBounds,
    },
  );

  expect(spansOf(distancesAt(resize, { x: 320, y: 40 }))).toEqual({
    horizontal: {
      start: Option.none,
      end: Option.some({ min: 320, max: 400 }),
    },
    vertical: { start: Option.some({ min: 20, max: 40 }), end: Option.none },
  });
});

test("左辺を引いて縮めると、左の距離は動かしたあとの左辺から測る", () => {
  const resize = grabbedWithTargets(
    { x: 0, y: 0.5 },
    { x: 100, y: 100 },
    {
      names: WithinParent,
      boundsByName: DrawnBounds,
    },
  );

  // 掴んだ時点の左辺 100 から測るなら 50〜100 になる
  expect(
    spansOf(distancesAt(resize, { x: 130, y: 100 })).horizontal.start,
  ).toEqual(Option.some({ min: 50, max: 130 }));
});

test("掴んだ辺が吸い付いたときは、吸い付いたあとの辺から測る", () => {
  const resize = grabbedWithTargets(
    { x: 1, y: 0.5 },
    { x: 300, y: 100 },
    {
      names: WithinParent,
      boundsByName: DrawnBounds,
    },
  );

  // 右辺は 197 で、上の兄弟の右辺 200 へ吸い付く
  expect(
    spansOf(distancesAt(resize, { x: 197, y: 100 })).horizontal.end,
  ).toEqual(Option.some({ min: 200, max: 400 }));
});

test("揃え先を外して（⌘ / Ctrl）吸い付かないときは、寄せない位置から測る", () => {
  const resize = NodeResize.withoutSnapTargets(
    grabbedWithTargets(
      { x: 1, y: 0.5 },
      { x: 300, y: 100 },
      {
        names: WithinParent,
        boundsByName: DrawnBounds,
      },
    ),
  );

  expect(
    spansOf(distancesAt(resize, { x: 197, y: 100 })).horizontal.end,
  ).toEqual(Option.some({ min: 197, max: 400 }));
});

test("距離の相手を外す（Alt / Option なし）と距離は出ず、吸い付きとガイド線は変わらない", () => {
  const resize = grabbedWithTargets(
    { x: 1, y: 0.5 },
    { x: 300, y: 100 },
    {
      names: WithinParent,
      boundsByName: DrawnBounds,
    },
  );
  const measuring = Option.unwrap(
    NodeResize.trackedAt(resize, { x: 197, y: 100 }, setupView()),
  );

  expect(
    NodeResize.trackedAt(
      NodeResize.withoutDistanceTargets(resize),
      { x: 197, y: 100 },
      setupView(),
    ),
  ).toEqual(Option.some({ ...measuring, distanceLines: FacingDistances.None }));
});

test("倍率 2 倍では、掴んだ辺は縮んだ量の 2 倍動いた位置から測る", () => {
  const resize = grabbedWithTargets(
    { x: 1, y: 0.5 },
    { x: 300, y: 100 },
    {
      names: WithinParent,
      boundsByName: DrawnBounds,
    },
  );
  const doubled: CanvasView = { ...CanvasView.create(), scale: 2 };

  // 画面で 40 引くと幅は 20 伸びる。倍率を戻し忘れると右辺は 320 になる
  expect(
    spansOf(distancesAt(resize, { x: 340, y: 100 }, doubled)).horizontal.end,
  ).toEqual(Option.some({ min: 340, max: 400 }));
});

test("右辺を左辺の向こうまで引いても、長さ 0 で止まった位置から測る", () => {
  const resize = grabbedWithTargets(
    { x: 1, y: 0.5 },
    { x: 300, y: 100 },
    {
      names: WithinParent,
      boundsByName: DrawnBounds,
    },
  );

  // ポインタは 40 にあるが、幅は 0 で止まり右辺は左辺 100 の位置に留まる
  expect(
    spansOf(distancesAt(resize, { x: 40, y: 100 })).horizontal.end,
  ).toEqual(Option.some({ min: 100, max: 400 }));
});

test("右下の角で高さが 0 で止まると、右の距離は出ず下の距離だけが出る", () => {
  const resize = grabbedWithTargets(
    { x: 1, y: 1 },
    { x: 300, y: 150 },
    {
      names: WithinParent,
      boundsByName: DrawnBounds,
    },
  );

  // 高さ 0 の起点は左右の相手と上下で重ならない
  expect(spansOf(distancesAt(resize, { x: 320, y: 0 }))).toEqual({
    horizontal: { start: Option.none, end: Option.none },
    vertical: { start: Option.none, end: Option.some({ min: 50, max: 200 }) },
  });
});

test("今の親を引けないときは距離が出ないが、兄弟には吸い付く", () => {
  const resize = grabbedWithTargets(
    { x: 1, y: 0.5 },
    { x: 300, y: 100 },
    {
      names: WithinParent,
      boundsByName: SiblingBounds,
    },
  );

  // 右辺は 197 で、上の兄弟の右辺 200 へ吸い付けば幅 100
  expect(
    Option.map(
      NodeResize.trackedAt(resize, { x: 197, y: 100 }, setupView()),
      ({ edit, distanceLines }) => ({ edit, distanceLines }),
    ),
  ).toEqual(
    Option.some({
      edit: ResizeEdit.create([{ axis: "width", length: 100 }]),
      distanceLines: FacingDistances.None,
    }),
  );
});

test("掴んだ時点の実測を載せていない掴みでは、距離は出ない", () => {
  const resize = grabbedAt(
    { ...setupResizable(), targets: { kind: "anyGrip", names: WithinParent } },
    { x: 1, y: 0.5 },
    { x: 300, y: 100 },
  );

  expect(distancesAt(resize, { x: 320, y: 100 })).toEqual(FacingDistances.None);
});

test("揃え先も距離の相手も無い掴み方（フロー配置の 2 軸の角）では、距離は出ない", () => {
  // 幅の 1 軸だけで効く相手なので、右下の角では名前が絞られて無くなる
  const resizable = {
    ...setupResizable(),
    targets: { kind: "axisOnly", axis: "width", names: WithinParent },
  } as const;
  const resize = grabbedWithMeasured(
    heldAt(resizable, { x: 1, y: 1 }, { x: 300, y: 150 }),
    DrawnBounds,
  );

  expect(distancesAt(resize, { x: 320, y: 170 })).toEqual(FacingDistances.None);
});

test("artboard の右辺を掴むと、右の動かない artboard までの距離が出る", () => {
  const resize = grabbedWithTargets(
    { x: 1, y: 0.5 },
    { x: 300, y: 100 },
    {
      names: { kind: "among-artboards", otherNames: ["intro", "settings"] },
      boundsByName: {
        intro: { left: -300, top: 50, width: 200, height: 100 },
        settings: { left: 500, top: 0, width: 200, height: 300 },
      },
    },
  );

  expect(spansOf(distancesAt(resize, { x: 320, y: 100 }))).toEqual({
    horizontal: {
      start: Option.none,
      end: Option.some({ min: 320, max: 500 }),
    },
    vertical: { start: Option.none, end: Option.none },
  });
});

test("掴んだ直後と離したあとは、今出す距離が無い", () => {
  const resize = grabbedWithTargets(
    { x: 1, y: 0.5 },
    { x: 300, y: 100 },
    {
      names: WithinParent,
      boundsByName: DrawnBounds,
    },
  );
  const tracked = Option.unwrap(
    NodeResize.trackedAt(resize, { x: 320, y: 100 }, setupView()),
  );
  const released = NodeResize.release(NodeResize.withLines(resize, tracked));

  expect([
    NodeResize.facingDistances(resize),
    NodeResize.facingDistances(released),
  ]).toEqual([FacingDistances.None, FacingDistances.None]);
});

test("掴んでいる状態に載せた距離が、今出す距離として返る", () => {
  const resize = grabbedWithTargets(
    { x: 1, y: 0.5 },
    { x: 300, y: 100 },
    {
      names: WithinParent,
      boundsByName: DrawnBounds,
    },
  );
  const tracked = Option.unwrap(
    NodeResize.trackedAt(resize, { x: 320, y: 100 }, setupView()),
  );

  expect(
    NodeResize.facingDistances(NodeResize.withLines(resize, tracked)),
  ).toEqual(tracked.distanceLines);
});

test("右辺を掴むと、右へだけ進む", () => {
  expect(
    ResizeGrip.toFacings(gripAt(setupResizable(), { x: 1, y: 0.5 })),
  ).toEqual([Right]);
});

test("左辺を掴むと、左へだけ進む", () => {
  expect(
    ResizeGrip.toFacings(gripAt(setupResizable(), { x: 0, y: 0.5 })),
  ).toEqual([Left]);
});

test("上辺を掴むと、上へだけ進む", () => {
  expect(
    ResizeGrip.toFacings(gripAt(setupResizable(), { x: 0.5, y: 0 })),
  ).toEqual([Top]);
});

test("右下の角を掴むと、右と下へ進む", () => {
  expect(
    ResizeGrip.toFacings(gripAt(setupResizable(), { x: 1, y: 1 })),
  ).toEqual([Right, Bottom]);
});

test("右上の角を掴むと、右と上へ進む", () => {
  expect(
    ResizeGrip.toFacings(gripAt(setupResizable(), { x: 1, y: 0 })),
  ).toEqual([Right, Top]);
});

test("左下の角を掴むと、左と下へ進む", () => {
  expect(
    ResizeGrip.toFacings(gripAt(setupResizable(), { x: 0, y: 1 })),
  ).toEqual([Left, Bottom]);
});

test("親の中の相手なら、左は親の縁まで、右は兄弟までの線になる", () => {
  expect(
    DistanceTargets.toDistances(
      {
        kind: "within-parent",
        parentBounds: { left: 0, top: 0, width: 200, height: 100 },
        siblings: [RightSibling],
      },
      From,
    ).horizontal,
  ).toEqual({
    start: Option.some({
      along: SidePairs.Horizontal,
      at: 45,
      span: { min: 0, max: 50 },
    }),
    end: Option.some({
      along: SidePairs.Horizontal,
      at: 45,
      span: { min: 70, max: 100 },
    }),
  });
});

test("artboard の間の相手なら、親の縁を測らず他の artboard だけを測る", () => {
  expect(
    DistanceTargets.toDistances(
      { kind: "among-artboards", others: [RightSibling] },
      From,
    ).horizontal,
  ).toEqual({
    start: Option.none,
    end: Option.some({
      along: SidePairs.Horizontal,
      at: 45,
      span: { min: 70, max: 100 },
    }),
  });
});

test("残す向きを 1 つ渡すと、4 方向に線があってもその向きの線だけが残る", () => {
  const distances = setupDistances();

  expect(
    FacingDistances.onlyToward(distances, [
      { pair: SidePairs.Horizontal, end: AxisEnds.End },
    ]),
  ).toEqual({
    horizontal: { start: Option.none, end: distances.horizontal.end },
    vertical: { start: Option.none, end: Option.none },
  });
});

test("角の 2 向きを渡すと、その 2 つだけが残る", () => {
  const distances = setupDistances();

  expect(
    FacingDistances.onlyToward(distances, [
      { pair: SidePairs.Horizontal, end: AxisEnds.End },
      { pair: SidePairs.Vertical, end: AxisEnds.Start },
    ]),
  ).toEqual({
    horizontal: { start: Option.none, end: distances.horizontal.end },
    vertical: { start: distances.vertical.start, end: Option.none },
  });
});

test("残す向きが空なら、どの向きにも線が無い", () => {
  expect(FacingDistances.onlyToward(setupDistances(), [])).toEqual(
    FacingDistances.None,
  );
});

test("辺の組と進む側が同じ向きは、別に作っても同じ向きとみなす", () => {
  expect(
    Facing.equals(Right, { pair: SidePairs.Horizontal, end: AxisEnds.End }),
  ).toBe(true);
});

test("辺の組が同じでも進む側が違えば、同じ向きとはみなさない", () => {
  expect(Facing.equals(Right, Left)).toBe(false);
});

test("進む側が同じでも辺の組が違えば、同じ向きとはみなさない", () => {
  expect(Facing.equals(Right, Down)).toBe(false);
});

test("写して値のあった要素だけが、元の並びの順に残る", () => {
  expect(
    ArrayEx.filterMap([3, -1, 2, -5, 4], (item) =>
      item > 0 ? Option.some(item * 10) : Option.none,
    ),
  ).toEqual([30, 20, 40]);
});

test("どの要素も写せなければ、写した並びは空になる", () => {
  expect(ArrayEx.filterMap(["a", "b"], () => Option.none)).toEqual([]);
});

test("掴んだ時点の実測を載せていない掴みでは、揃え先の近くでも寄せない", () => {
  // 上と同じ動かし方。載せていれば 240 になる
  const resize = grabbedAt(
    setupResizable(),
    { x: 1, y: 0.5 },
    { x: 300, y: 100 },
  );

  expect(resizeEditAt(resize, { x: 337, y: 100 }, setupView())).toEqual(
    Option.some(ResizeEdit.create([{ axis: "width", length: 237 }])),
  );
});

test("掴んだ時点の実測を載せていない掴みでは、揃え先の近くでもガイド線は出ない", () => {
  const resize = grabbedAt(
    setupResizable(),
    { x: 1, y: 0.5 },
    { x: 300, y: 100 },
  );

  const tracked = NodeResize.trackedAt(resize, { x: 337, y: 100 }, setupView());

  expect(Option.map(tracked, ({ guides }) => guides)).toEqual(
    Option.some(SideSnap.NoGuides),
  );
});

